{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "snapshot_card",
        "feedback_card",
        "actions_card"
      ]
    },
    "snapshot_card": {
      "type": "Card",
      "props": {},
      "children": [
        "snapshot_header_stack",
        "snapshot_description"
      ]
    },
    "snapshot_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "snapshot_icon",
        "snapshot_title"
      ]
    },
    "snapshot_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/graph-up-arrow.svg"
      },
      "children": []
    },
    "snapshot_title": {
      "type": "Text",
      "props": {
        "text": "Customer Experience Snapshot",
        "variant": "h2"
      },
      "children": []
    },
    "snapshot_description": {
      "type": "Text",
      "props": {
        "text": "This overview highlights key customer feedback scores across various service and product categories."
      },
      "children": []
    },
    "feedback_card": {
      "type": "Card",
      "props": {},
      "children": [
        "feedback_title",
        "feedback_table",
        "feedback_summary"
      ]
    },
    "feedback_title": {
      "type": "Text",
      "props": {
        "text": "Feedback Score Breakdown",
        "variant": "h2"
      },
      "children": []
    },
    "feedback_table": {
      "type": "Table",
      "props": {
        "title": "Customer Feedback Scores",
        "domain": "generic",
        "preferredPresentation": "cards",
        "primaryColumn": "Category",
        "highlightColumns": ["Score"],
        "columns": [
          {
            "key": "Category",
            "label": "Category"
          },
          {
            "key": "Score",
            "label": "Score"
          }
        ],
        "rows": [
          {
            "Category": "Product Quality",
            "Score": 4.5
          },
          {
            "Category": "Customer Service",
            "Score": 3.8
          },
          {
            "Category": "Delivery Speed",
            "Score": 4.2
          },
          {
            "Category": "Pricing",
            "Score": 3.0
          },
          {
            "Category": "Website Usability",
            "Score": 4.7
          }
        ]
      },
      "children": []
    },
    "feedback_summary": {
      "type": "Text",
      "props": {
        "text": "Based on the feedback data, Pricing is the area identified as needing the most improvement, with a score of 3.0."
      },
      "children": []
    },
    "actions_card": {
      "type": "Card",
      "props": {},
      "children": [
        "actions_title",
        "submit_feedback_button",
        "view_report_button"
      ]
    },
    "actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "submit_feedback_button": {
      "type": "Button",
      "props": {
        "label": "Provide Feedback"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/feedback-form"
          }
        }
      }
    },
    "view_report_button": {
      "type": "Button",
      "props": {
        "label": "Analytics Dashboard"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/analytics-dashboard"
          }
        }
      }
    }
  }
}
